INSERT INTO public."conversation_feedbacks" ("id", "better_sentences", "grammar_corrections", "summary", "vocabulary_suggestions", "session_id") VALUES ('87', 'Instead of "How about you any plans today" you could say "Do you have any plans for today?". Replace "Sounds nice enjoy" with "That sounds nice, enjoy!". Change "I like travel" to "I love traveling" or "I enjoy traveling to new places."', '1. "How about you any plans today" → "Do you have any plans for today?" 2. "Sounds nice enjoy" → "Sounds nice, enjoy!" or "Sounds nice, enjoy your walk." 3. "I like travel" → "I like traveling" or "I like to travel." 4. "hello" → capitalize as "Hello."', 'The student can convey basic ideas but often uses incomplete sentences and makes frequent grammatical errors. Vocabulary is limited to simple, everyday words, and the conversation lacks natural flow. Pronunciation seems understandable, but there is room for improvement in intonation and stress.', 'use phrases like "Do you have any plans for today?", "That sounds interesting", "I enjoy traveling", "I’d like to improve my spoken English", and expressions such as "Sounds great!" or "That’s wonderful!"', '257') ON CONFLICT DO NOTHING;
INSERT INTO public."conversation_feedbacks" ("id", "better_sentences", "grammar_corrections", "summary", "vocabulary_suggestions", "session_id") VALUES ('88', 'Tap the microphone to speak with your AI tutor next time!', 'No dialogue to evaluate.', 'Session ended with no speaking activity.', 'No vocabulary practiced.', '369') ON CONFLICT DO NOTHING;
INSERT INTO public."conversation_feedbacks" ("id", "better_sentences", "grammar_corrections", "summary", "vocabulary_suggestions", "session_id") VALUES ('89', 'Tap the microphone to speak with your AI tutor next time!', 'No dialogue to evaluate.', 'Session ended with no speaking activity.', 'No vocabulary practiced.', '371') ON CONFLICT DO NOTHING;
INSERT INTO public."conversation_feedbacks" ("id", "better_sentences", "grammar_corrections", "summary", "vocabulary_suggestions", "session_id") VALUES ('90', 'Tap the microphone to speak with your AI tutor next time!', 'No dialogue to evaluate.', 'Session ended with no speaking activity.', 'No vocabulary practiced.', '373') ON CONFLICT DO NOTHING;
INSERT INTO public."conversation_feedbacks" ("id", "better_sentences", "grammar_corrections", "summary", "vocabulary_suggestions", "session_id") VALUES ('91', 'Instead of "I''m excited, thanks" you could say, "I''m really excited about the new term, thank you!"; for "Got it thanks" try, "Got it, thanks!"; and you might expand "What classes are you taking this term?" to "Could you tell me which classes you''re taking this term?"', 'Add commas for natural pauses (e.g., "Got it, thanks.") and consider using complete sentences when responding (e.g., "I''m excited, thank you!").', 'The student showed enthusiasm about the upcoming term and asked a clarification question, but responses were very brief and lacked detail, limiting the assessment of fluency and pronunciation.', '"really excited", "looking forward to", "mix of things", "cooking class for fun"', '384') ON CONFLICT DO NOTHING;
INSERT INTO public."conversation_feedbacks" ("id", "better_sentences", "grammar_corrections", "summary", "vocabulary_suggestions", "session_id") VALUES ('92', 'I would like a Coke and a burger, please.\nI would like to order a cappuccino and a pastry.\nDo you have any pastries?\nI would like a crescent pastry.\nCould I have the bill, please?\nThe total is $12. I would like to pay now.', 'Missing articles ("a" before coke, burger, cappuccino, pastry), incorrect verb forms ("would like to have" should be "would like a"), subject‑verb agreement errors, use of proper nouns instead of nouns ("Prashant" instead of "pastry"), and lack of punctuation and capitalization at the start of sentences.', 'The student was able to convey basic ordering ideas but struggled with word choice, article usage, and sentence structure, leading to misunderstandings. Vocabulary was limited to a few food‑related terms, and many sentences were fragments or contained incorrect words.', 'coke, burger, cappuccino, pastry, crescent pastry, bill, total, pay, order, drink, snack', '387') ON CONFLICT DO NOTHING;
INSERT INTO public."conversation_feedbacks" ("id", "better_sentences", "grammar_corrections", "summary", "vocabulary_suggestions", "session_id") VALUES ('97', '• "Hi! I''m happy to practice English with you today." (good)  → "Hello! I''m excited to practice English with you today." • "talk about my hobbies" → "I would like to talk about my hobbies." • "hey how are you" → "Hey, how are you?"', '1. "talk about my hobbies" should be a complete sentence, e.g., "I would like to talk about my hobbies." 2. "hey how are you" needs capitalization and punctuation: "Hey, how are you?" 3. Consistent use of subject pronouns, e.g., "I am happy to practice English with you today."', 'The student showed willingness to speak but used very short, sometimes incomplete sentences and limited vocabulary. Grammar errors were minor but noticeable, and fluency was low due to brief responses.', 'hobbies, reading, cooking, I would like to, could you tell me about, how about you, I''m happy to practice', '417') ON CONFLICT DO NOTHING;
INSERT INTO public."conversation_feedbacks" ("id", "better_sentences", "grammar_corrections", "summary", "vocabulary_suggestions", "session_id") VALUES ('99', 'Tap the microphone to speak with your AI tutor next time!', 'No dialogue to evaluate.', 'Session ended with no speaking activity.', 'No vocabulary practiced.', '426') ON CONFLICT DO NOTHING;
