INSERT INTO public."vocabulary" ("id", "antonym", "created_at", "example_sentence", "favorite", "meaning", "synonym", "word", "user_id", "student_id", "collocations", "level", "mastered", "part_of_speech", "phonetic") VALUES ('40', 'non‑sport, inactivity, silence, stillness', '2026-09-16T11:22:38.565Z', 'She cheered loudly as her favorite team scored a boundary in the cricket match.', false, 'A bat-and-ball team sport played between two sides of eleven players on a field with a 22-yard pitch at its centre, or the insect known for its chirping sound.', 'sport, bat-and-ball game, pastime, insect, orthopteran', 'Cricket', '152', NULL, 'cricket match, cricket bat, cricket field, cricket season, cricket player, cricket ground, cricket equipment', 'Intermediate', false, 'noun', '/ˈkrɪkɪt/') ON CONFLICT DO NOTHING;
