INSERT INTO public."vocabulary" ("id", "antonym", "created_at", "example_sentence", "favorite", "meaning", "synonym", "word", "user_id", "student_id", "collocations", "level", "mastered", "part_of_speech", "phonetic") VALUES ('47', 'steady, predictable, consistent, stable, reliable, constant', '2026-09-16T11:27:37.505Z', 'The CEO''s capricious decisions left the employees uncertain about the company''s direction.', false, 'Having a tendency to change one''s mind or behavior suddenly and unpredictably; impulsive and whimsical.', 'fickle, whimsical, unpredictable, erratic, impulsive, mercurial, flighty', 'Capricious', '94', NULL, 'capricious weather, capricious behavior, capricious decision, capricious nature', 'Advanced', false, 'adjective', '/kəˈprɪʃəs/') ON CONFLICT DO NOTHING;
